def run_job(job, policy, results):
    if not isinstance(job, dict):
        syntax()
    if "raw" in job:
        text = job["raw"]
        if not isinstance(text, str):
            syntax()
    else:
        source = job.get("source")
        if not isinstance(source, int) or isinstance(source, bool):
            raise Reject("upstream")
        if source < 0 or source >= len(results):
            raise Reject("upstream")
        previous = results[source]
        if previous.get("status") != "accept":
            raise Reject("upstream")
        text = previous["wire"]
    gateway = job.get("gateway")
    req = parse_request(text)
    return evaluate(req, policy, gateway, job.get("ingress"), job.get("trusted_out"))


def process(batch):
    policy = Policy(batch.get("directory") or {}, batch.get("accounts") or {},
                    batch.get("gateways") or {})
    results = []
    for job in batch.get("jobs") or []:
        try:
            results.append(run_job(job, policy, results))
        except Reject as exc:
            results.append({"status": "reject", "reason": exc.reason})
        except Exception:  # pragma: no cover - defensive only
            results.append({"status": "reject", "reason": "syntax"})
    return {"results": results}


def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:  # pragma: no cover - defensive only
        data = b""
    try:
        batch = json.loads(data.decode("utf-8"))
    except Exception:
        batch = None
    if isinstance(batch, dict):
        try:
            output = process(batch)
        except Exception:  # pragma: no cover - defensive only
            output = {"results": []}
    else:
        output = {"results": []}
    sys.stdout.write(json.dumps(output))
    sys.stdout.write("\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
